/* Editor em itens; campos textuais compatíveis com impressão e requisição existentes. */
(()=>{'use strict';const M=MartinsItens,$=id=>document.getElementById(id),controllers={};const css=document.createElement('style');css.textContent='.rdi-editor{margin:8px 0}.rdi-input{box-sizing:border-box;width:100%;padding:11px;background:#f8fafc;border:1px solid #cbd5e1;border-radius:9px;font:inherit;font-size:13px}.rdi-actions{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0}.rdi-actions button,.rdi-row button{min-height:42px;padding:8px 12px;border-radius:8px;font-size:12px;font-weight:700}.rdi-add{background:#f59e0b;color:#020617}.rdi-cancel{background:#e2e8f0;color:#334155}.rdi-row{padding:10px;background:white;border:1px solid #e2e8f0;border-radius:9px;margin:7px 0}.rdi-text{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;color:#334155}.rdi-row button{background:#f1f5f9;color:#334155;margin:6px 6px 0 0}.rdi-row button[data-action=remove]{background:#fff1f2;color:#be123c}.rdi-note,.rdi-empty{font-size:11px;line-height:1.5;color:#64748b}.rdi-count{font-size:11px;font-weight:800;color:#92400e}.rdi-status{font-size:12px;color:#92400e}@media print{.rdi-editor{display:none}}';document.head.append(css);
for(const [kind,title] of [['materiais','material'],['ocorrencias','ocorrência']]){const field=$('textarea-'+kind);if(!field)continue;const box=document.createElement('div');box.className='rdi-editor';box.id='rdi-'+kind;const count=document.createElement('p');count.className='rdi-count';const input=document.createElement('textarea');input.id='rdo-item-'+kind;input.className='rdi-input';input.rows=2;input.placeholder='Descreva um item e toque em Adicionar';for(const label of document.querySelectorAll('label[for="'+field.id+'"]'))label.htmlFor=input.id;const actions=document.createElement('div');actions.className='rdi-actions';const add=document.createElement('button');add.type='button';add.id='rdi-add-'+kind;add.className='rdi-add';add.textContent='+ Adicionar '+title;const cancel=document.createElement('button');cancel.type='button';cancel.className='rdi-cancel';cancel.textContent='Cancelar edição';cancel.hidden=true;const note=document.createElement('p');note.className='rdi-note';note.textContent='Adicione um item por vez. Ao salvar o RDO, o item que estiver digitado também será incluído. Conteúdo antigo é preservado como um item até você editá-lo.';const rows=document.createElement('div');rows.id='rdi-list-'+kind;const status=document.createElement('p');status.className='rdi-status';status.setAttribute('role','status');actions.append(add,cancel);box.append(count,input,actions,note,rows,status);field.before(box);field.hidden=true;field.style.display='none';field.setAttribute('aria-hidden','true');let state=M.load(field.value),editing=null,last=field.value;
function write(){field.value=M.text(state);last=field.value;}
function cancelEdit(){editing=null;input.value='';cancel.hidden=true;add.textContent='+ Adicionar '+title;}
function external(){if(field.value!==last){if(editing!==null||input.value.trim())throw Error('O texto de '+kind+' mudou em outra ação. Guarde o item digitado e atualize o formulário antes de continuar.');state=M.load(field.value);last=field.value;render();}}
function render(){count.textContent=state.items.length+' item(ns)';rows.replaceChildren();if(!state.items.length){const empty=document.createElement('p');empty.className='rdi-empty';empty.textContent='Nenhum item adicionado.';rows.append(empty);}state.items.forEach((item,i)=>{const row=document.createElement('div');row.className='rdi-row';const text=document.createElement('p');text.className='rdi-text';text.textContent=(i+1)+'. '+item.texto;const edit=document.createElement('button');edit.type='button';edit.textContent='Editar';edit.setAttribute('aria-label','Editar '+title+' '+(i+1));edit.onclick=()=>{try{external();if(editing!==null||input.value.trim())throw Error('Salve ou cancele o item em edição antes de abrir outro.');editing=i;input.value=state.items[i].texto;add.textContent='Salvar item';cancel.hidden=false;input.focus();}catch(e){status.textContent=e.message;}};const remove=document.createElement('button');remove.type='button';remove.dataset.action='remove';remove.textContent='Remover';remove.setAttribute('aria-label','Remover '+title+' '+(i+1));remove.onclick=()=>{try{external();state=M.remove(state,i);if(editing===i)cancelEdit();else if(editing!==null&&editing>i)editing--;write();render();status.textContent='Item removido do formulário. O RDO salvo não foi alterado.';}catch(e){status.textContent=e.message;}};row.append(text,edit,remove);rows.append(row);});}
function flush(){external();if(input.value.trim()||editing!==null){state=M.change(state,editing,input.value);cancelEdit();write();render();}return state;}
add.onclick=()=>{try{external();state=M.change(state,editing,input.value);cancelEdit();write();render();status.textContent='Item incluído no formulário. Salve o RDO para registrar.';}catch(e){status.textContent=e.message;}};cancel.onclick=()=>{cancelEdit();status.textContent='Edição do item cancelada.';};controllers[kind]={load(text,list){state=M.load(text,list);cancelEdit();write();render();status.textContent='';},flush,items(){return state.items.map(x=>({...x}));}};render();}
window.MartinsRdoItens={carregar(rdo={}){for(const kind of Object.keys(controllers))controllers[kind].load(rdo[kind]||'',rdo[kind+'Lista']);},sincronizar(){for(const c of Object.values(controllers))c.flush();},exportar(){return Object.fromEntries(Object.entries(controllers).map(([k,c])=>[k+'Lista',c.items()]));}};
for(const kind of Object.keys(controllers))$('textarea-'+kind).addEventListener('input',()=>{try{controllers[kind].flush();}catch(e){showToast(e.message,'warning');}});
const requisitar=window.abrirRequisicaoMaterialDoRdo;if(typeof requisitar==='function')window.abrirRequisicaoMaterialDoRdo=function(...args){try{controllers.materiais?.flush();const result=requisitar.apply(this,args);if(Array.isArray(window.currentItensPedido)){window.currentItensPedido=controllers.materiais.items().map(x=>({material:x.texto,qtd:1,unid:'un',aplicacao:'Canteiro de obras'}));window.renderItensPedidoTable?.();}return result;}catch(e){showToast(e.message,'warning');}};
document.addEventListener('DOMContentLoaded',()=>{for(const kind of Object.keys(controllers))controllers[kind].load($('textarea-'+kind).value);});
})();
